local UIMazeBagItemEffectNode = Class("UIMazeBagItemEffectNode")
function UIMazeBagItemEffectNode:__init() 
    self._smallCardLoader = nil
    self._itemLoader = nil
end

function UIMazeBagItemEffectNode:__delete()
    self._smallCardLoader = nil
    self._itemLoader = nil
end

function UIMazeBagItemEffectNode:Awake()
end

function UIMazeBagItemEffectNode:Start()
end

function UIMazeBagItemEffectNode:Refresh(data)
    if not data then
        return
    end

    if not self._itemLoader then
        self._itemLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
    end
    if self._itemLoader.IsSuccess then
        local go = self.item.transform:Find("item")
        if not go then 
            go = CfUtils.InstantiateGo(self._itemLoader.ResultObject, self.item)
            go.name = "item"
        end
        if go then
            CfUtils.RefeshGoodGo(go, data.refId, nil, 64/154, Constants.IDArea.Maze)
        end
    end

    CfUtils.FillText(self.name, data.name)
    KTool.SetActive(self.controller.gameObject, true)
end

function UIMazeBagItemEffectNode:RefreshHero(data)
    if not data then
        return
    end
    local cardData
    if data.isAssistant == 1 then 
        local assistRole = CfUtils.GetCfVo(AutoIds.IdSetting361, "MazeAssistRoleVo", data.id)
        cardData = CardConfMgr:GetCardByRefId(assistRole.cardId)
        cardData.cardId = assistRole.cardId
    else
        cardData = cardComp:GetCardById(checkString(data.id))
    end
    if not cardData then
        return
    end

    if not self._smallCardLoader then
        self._smallCardLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSmallHeadNode.prefab", nil, true)
    end
    if self._smallCardLoader.IsSuccess then
        local go = self.item.transform:Find("cell")
        if not go then 
            go = CfUtils.InstantiateGo(self._smallCardLoader.ResultObject, self.item)
            go.name = "cell"
        end
        if go then
            CfUtils.RefeshCommonSmallHeroGo(go, cardData, Vector3(0.35, 0.35, 1))
            go.transform.localPosition = Vector3(3, -4, 0)
        end
    end

    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardData.cardId)
    if cardVo then
        CfUtils.FillText(self.name, cardVo.name)
    end
    KTool.SetActive(self.controller.gameObject, true)
end

function UIMazeBagItemEffectNode:OnDestroy()
    if not isNull(self._smallCardLoader) then
        self._smallCardLoader:Release()
        self._smallCardLoader = nil
    end
    if not isNull(self._itemLoader) then
        self._itemLoader:Release()
        self._itemLoader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMazeBagItemEffectNode
